# ==================== FLASK ДЛЯ RENDER ====================
def start_flask():
    try:
        from flask import Flask
        app = Flask(__name__)
        
        @app.route('/')
        def home():
            return "🤖 KORECKT BOT is running!"
        
        @app.route('/health')
        def health():
            return "OK"
        
        port = int(os.environ.get("PORT", 8080))
        app.run(host="0.0.0.0", port=port, debug=False)
    except Exception as e:
        print(f"Flask error: {e}")

